from typing import List
from dataclasses import dataclass

@dataclass
class GridCell:
    cell_id: str
    name: str
    state: str
    lat: float
    lon: float
    lat_min: float
    lat_max: float
    lon_min: float
    lon_max: float
    risk_profile: List[str]
    population_density: int
    
    @property
    def bbox(self) -> dict:
        return {"lat_min": self.lat_min, "lat_max": self.lat_max, "lon_min": self.lon_min, "lon_max": self.lon_max}

